  status: IssueStatus,
  at: IsoTimestamp,
): Issue {
  if (issue.status === status) return issue;
  const closing = isClosedStatus(status);
  return {
    ...issue,
    status,
    updatedAt: at,
    startedAt:
      issue.startedAt === null && status === "in_progress" ? at : issue.startedAt,
    completedAt: closing ? (issue.completedAt ?? at) : null,
  };
}

