      const source = readFileSync(join(ROOT, file), "utf8");
      const spec = moduleSpecifier(file);
      for (const match of source.matchAll(EXPORT_RE)) {
        const name = match[1];
        if (name && !table.has(name)) table.set(name, spec);
      }
    }
  }",
